import { useState } from "react";

type Step = "design" | "predict" | "evidence" | "conclude";
const STEPS: Array<{ id: Step; label: string }> = [
  { id: "design", label: "Study design" }, { id: "predict", label: "Make a prediction" },
  { id: "evidence", label: "Read the kidney evidence" }, { id: "conclude", label: "Make a conclusion" },
];

export function CisplatinPractical({ onExit }: { onExit: () => void }) {
  const [step, setStep] = useState<Step>("design");
  const [answer, setAnswer] = useState<string | null>(null);
  const current = STEPS.findIndex((item) => item.id === step);
  const next = () => { setAnswer(null); setStep(STEPS[Math.min(current + 1, STEPS.length - 1)]!.id); };
  const choices = (items: Array<[string, string]>) => <div className="lesson-choices vertical">{items.map(([value, label]) => <button key={value} type="button" aria-pressed={answer === value} onClick={() => setAnswer(value)}>{label}</button>)}</div>;

  return <main id="main" className="learn-case-page">
    <header className="learn-case-header"><div><span className="eyebrow">VAST classroom · Practical 03</span><h1>Cisplatin and the rat kidney</h1><p>Use a published rat study to recognise tubular injury without overstating what one study proves.</p></div><button type="button" className="ghost" onClick={onExit}>← All Learn practicals</button></header>
    <div className="learn-case-progress" aria-label="Practical progress"><span style={{ width: `${((current + 1) / STEPS.length) * 100}%` }} /></div>
    <nav className="learn-case-steps" aria-label="Cisplatin practical steps">{STEPS.map((item, index) => <button key={item.id} type="button" aria-current={item.id === step ? "step" : undefined} onClick={() => { setAnswer(null); setStep(item.id); }}><small>{String(index + 1).padStart(2, "0")}</small><span><b>{item.label}</b><em>{index === 0 ? "Control and injury arm" : index === 1 ? "Commit before reveal" : index === 2 ? "Published pathology" : "Evidence-aware judgement"}</em></span></button>)}</nav>
    <section className="published-case lesson-screen learn-case-content" key={step}>
      {step === "design" && <><div className="lesson-opening"><div><span className="published-badge">Published case · CC BY 4.0</span><span className="eyebrow">Question</span><h2>What does cisplatin kidney injury look like in a controlled rat study?</h2><p>First identify the comparison. The reference case is an injury model, not a dose-finding study.</p></div><div className="lesson-molecule"><span>CIS</span><small>Primary focus<br /><b>Kidneys</b></small></div></div><div className="lesson-brief"><span className="eyebrow">Published study card</span><h3>One cisplatin injury arm versus vehicle control</h3><div><span>Test model<b>Male Sprague–Dawley rats</b></span><span>Injury dose<b>7 mg/kg · intraperitoneal</b></span><span>Groups<b>Vehicle n=6 · cisplatin n=6</b></span><span>Readout<b>Kidney assessment on day 14</b></span></div><p>Khallaf et al. also tested a protective treatment. This practical uses only the untreated control and cisplatin injury arms.</p></div>{choices([["control", "The control establishes what normal kidney tissue looks like without cisplatin."], ["controlless", "The control is unnecessary because cisplatin is already known to be nephrotoxic."]])}{answer && <p className={answer === "control" ? "correct" : "incorrect"} role="status">{answer === "control" ? "Correct. A known drug still needs an appropriate comparator in a specific study." : "Not quite. Prior knowledge cannot replace the study’s baseline."}{answer === "control" && <button className="primary lesson-continue" onClick={next}>Make your prediction →</button>}</p>}</>}
      {step === "predict" && <><div className="lesson-heading"><div><span className="eyebrow">Prediction checkpoint</span><h2>Predict the tissue-level response.</h2><p>The source will reveal pathology at one dose and one terminal time point—not a full dose-response curve.</p></div><span className="lesson-number">02</span></div>{choices([["tubular", "Cisplatin will produce tubular injury compared with vehicle control."], ["healthy", "Both groups will have identical normal renal tissue."], ["noael", "This single exposure will establish a precise NOAEL."]])}{answer && <p className={answer === "tubular" ? "correct" : "incorrect"} role="status">{answer === "tubular" ? "A sound, testable prediction. Now compare it with the reported pathology." : "That conclusion is not supported by the study design."}{answer === "tubular" && <button className="primary lesson-continue" onClick={next}>Reveal the evidence →</button>}</p>}</>}
      {step === "evidence" && <><div className="lesson-heading"><div><span className="eyebrow">Published observation · Table 2</span><h2>Read the renal pathology.</h2><p>All findings below are directly transcribed from the cisplatin-only arm at day 14.</p></div><span className="lesson-number">03</span></div><ol className="published-timeline lesson-timeline"><li><span>7 mg/kg · day 14</span><b>Moderate (++): degeneration</b><p>Renal tubular tissue showed moderate degeneration.</p></li><li><span>7 mg/kg · day 14</span><b>Moderate (++): cast formation and tubular necrosis</b><p>Two strong pathology signals in the cisplatin-only arm.</p></li><li><span>7 mg/kg · day 14</span><b>Mild (+): brush-border loss and dilation</b><p>Additional signs consistent with tubular injury.</p></li></ol><div className="banner info"><b>Limit:</b> serum creatinine and urea are shown graphically in the paper and are not displayed here as exact numbers until independently checked.</div>{choices([["supported", "At 7 mg/kg in this model, cisplatin was associated with tubular pathology by day 14."], ["safe", "All lower cisplatin doses are proven safe."], ["human", "This determines the safe human cisplatin dose."]])}{answer && <p className={answer === "supported" ? "correct" : "incorrect"} role="status">{answer === "supported" ? "Correct. It is specific to the tested model, exposure and time point." : "That statement reaches beyond the evidence."}{answer === "supported" && <button className="primary lesson-continue" onClick={next}>Make your conclusion →</button>}</p>}</>}
      {step === "conclude" && <><div className="lesson-finale"><span className="lesson-complete">Practical complete</span><h2>You separated a finding from a claim.</h2><p>The published study supports kidney tubular injury after its specific cisplatin regimen. It does not by itself establish a NOAEL, a universal dose-response relationship, or human safety.</p><div className="lesson-recap"><span><b>Design</b>Vehicle control versus 7 mg/kg cisplatin</span><span><b>Observation</b>Tubular degeneration, casts and necrosis</span><span><b>Judgement</b>Supported for this rat model at day 14</span><span><b>Next</b>Compare with the labelled sandbox kidney model</span></div></div><a className="primary lesson-continue" href="#lab">Open the kidney model sandbox →</a><details className="lesson-evidence"><summary>Evidence and source</summary><p>Khallaf EK et al. <i>Scientific Reports</i> 2026;16:15227. DOI: 10.1038/s41598-026-50755-0. Open access under CC BY 4.0.</p></details></>}
    </section>
  </main>;
}
